43: function advanceClock(sec){state.clock=Math.max(0,state.clock-sec);if(state.clock===0){if(state.quarter<4){state.quarter++;state.clock=900;addFeed(`End of quarter. ${['','Second','Third','Fourth'][state.quarter-1]} quarter begins.`)}else endGame()}}
