const fs=require('fs'); const {createRequire}=require('module');
const runtime=process.env.HOME+'/.local/share/omgithub-playwright'; const req=createRequire(runtime+'/package.json'); const {chromium}=req('playwright');
(async()=>{
 const config=JSON.parse(fs.readFileSync(runtime+'/linux.json','utf8'));
 const browser=await chromium.launch({...config.browser.launchOptions});
 const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1});
 const errors=[]; page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3000',{waitUntil:'load'});
 await page.locator('[data-mode="cpu"]').click();
 await page.getByRole('button',{name:/Inside Run/}).click();
 await page.getByRole('button',{name:/SNAP THE BALL/}).click();
 await page.locator('.roll-result').waitFor();
 const firstClock=await page.locator('#clockLabel').textContent();
 await page.screenshot({path:'/tmp/opencode/sunday-showdown.jpg',type:'jpeg',quality:72});
 await page.locator('#newGameBtn').click();
 await page.locator('[data-mode="pass"]').click();
 await page.getByRole('button',{name:/Short Pass/}).click();
 await page.getByRole('button',{name:/SNAP THE BALL/}).click();
 const privateText=await page.locator('#cardMatch').innerText();
 if(!privateText.includes('Play call hidden')||privateText.includes('Short Pass')) throw new Error('Pass-and-play call was not hidden during handoff');
 await page.getByRole('button',{name:/DEFENSE IS READY/}).click();
 await page.getByRole('button',{name:/Run Blitz/}).click();
 await page.getByRole('button',{name:/REVEAL THE PLAY/}).click();
 await page.locator('.roll-result').waitFor();
 const passClock=await page.locator('#clockLabel').textContent();
 const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
 if(errors.length) throw new Error(errors.join('\n'));
 console.log(JSON.stringify({cpuFirstPlayClock:firstClock,passAndPlayClock:passClock,hiddenCall:true,horizontalOverflow:overflow,screenshot:'/tmp/opencode/sunday-showdown.jpg'},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
