const fs=require('fs'); const {createRequire}=require('module');
const runtime=process.env.HOME+'/.local/share/omgithub-playwright'; const req=createRequire(runtime+'/package.json'); const {chromium}=req('playwright');
(async()=>{
 const config=JSON.parse(fs.readFileSync(runtime+'/linux.json','utf8'));
 const browser=await chromium.launch({...config.browser.launchOptions});
 const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3000');
 // CPU touchdown and extra point
 await page.evaluate(()=>Math.random=()=>.5);
 await page.locator('[data-mode="cpu"]').click();
 for(let i=0;i<30 && !(await page.locator('#cardMatch').innerText()).includes('Go for one or two?');i++){
   const txt=await page.locator('#cardMatch').innerText();
   if(txt.includes('choose a play')) {await page.getByRole('button',{name:/Inside Run/}).click();await page.getByRole('button',{name:/SNAP THE BALL/}).click()}
   else if(txt.includes('call the counter')) {await page.getByRole('button',{name:/Run Blitz/}).click();await page.getByRole('button',{name:/REVEAL THE PLAY/}).click()}
   else await page.waitForTimeout(20);
 }
 const touchdown=await page.locator('#cardMatch').innerText();
 if(!touchdown.includes('Go for one or two?')) throw new Error('TD/conversion scenario did not reach conversion');
 await page.getByRole('button',{name:/Extra point/}).click();
 if(!(await page.locator('#homeScore').textContent()).includes('7')) throw new Error('Extra point did not add seven total points');
 // Punt on fourth down after three deliberately unsuccessful plays.
 await page.locator('#newGameBtn').click();await page.locator('[data-mode="cpu"]').click();await page.evaluate(()=>Math.random=()=>.999);
 for(let i=0;i<3;i++){await page.getByRole('button',{name:/Inside Run/}).click();await page.getByRole('button',{name:/SNAP THE BALL/}).click()}
 const fourth=await page.locator('#cardMatch').innerText();
 if(!fourth.includes('Punt')) throw new Error('Punt was not offered on fourth down');
 await page.getByRole('button',{name:/Punt/}).click();await page.getByRole('button',{name:/SNAP THE BALL/}).click();
 const puntDone=await page.locator('#cardMatch').innerText();
 if(!puntDone.includes('CPU offense')) throw new Error('Punt did not switch possession to CPU');
 // Quarter transitions with low outcomes and pass-and-play; each play consumes 30 seconds.
 await page.locator('#newGameBtn').click();await page.locator('[data-mode="pass"]').click();
 for(let i=0;i<34;i++){
   let txt=await page.locator('#cardMatch').innerText();
   if(txt.includes('choose a play')){await page.getByRole('button',{name:/Inside Run/}).click();await page.getByRole('button',{name:/SNAP THE BALL/}).click()}
   else if(txt.includes('Play call hidden')) await page.getByRole('button',{name:/DEFENSE IS READY/}).click();
   else if(txt.includes('call the counter')){await page.getByRole('button',{name:/Run Blitz/}).click();await page.getByRole('button',{name:/REVEAL THE PLAY/}).click()}
   else break;
   if((await page.locator('#quarterLabel').textContent()).includes('2ND')) break;
 }
 const quarter=await page.locator('#quarterLabel').textContent();
 if(!quarter.includes('2ND')) throw new Error(`Quarter did not advance: ${quarter}`);
 if(errors.length)throw new Error(errors.join('\n'));
 console.log(JSON.stringify({touchdownAndExtraPoint:true,homeScore:await page.locator('#homeScore').textContent(),puntAndPossession:true,nextQuarter:quarter,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
